opy"],"text":"Yesca impermeable."}]$verify_5a550d7290d04ac0$::jsonb and payload#>'{catalog,revision}'=$verify_6b86b273ff34fce1$1$verify_6b86b273ff34fce1$::jsonb and revision=2) union all select 'inventory:inv_4852ea9397914f320ed77d587f339159' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_800d3e58b5b497357fe501c441398697' and entity_id='inv_4852ea9397914f320ed77d587f339159' and payload#>'{features}'=$verify_7bc718f5417070c9$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cada uno de los tres compartimentos de esta aljaba está conectado con un espacio extradimensional, lo que le permite contener muchos objetos sin pesar nunca más de 1 kg. El compartimento más pequeño puede albergar hasta 60 flechas, virotes u objetos similares. El compartimento intermedio puede contener hasta 18 jabalinas u objetos parecidos. En el compartimento más grande caben hasta 6 objetos largos, como arcos, bastones o lanzas.\n\nPuedes extraer cualquier objeto que contenga esta aljaba igual que lo harías con una aljaba o vaina normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_7bc718f5417070c9$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2))t;